PAGE_HTML = r'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#090b10"><title>Baixador Universal</title>
<style>
:root{color-scheme:dark;--bg:#090b10;--panel:#131823e8;--text:#f5f7fb;--muted:#99a4b6;--line:#ffffff16;--a:#785cff;--b:#42d9b6;--err:#ff7086}*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:Inter,system-ui,sans-serif;color:var(--text);background:radial-gradient(circle at 10% 10%,#785cff2c,transparent 32rem),radial-gradient(circle at 90% 90%,#42d9b61d,transparent 28rem),var(--bg)}main{width:min(920px,calc(100% - 28px));margin:auto;padding:58px 0 40px}.brand{color:var(--muted);text-transform:uppercase;letter-spacing:.13em;font-size:.8rem;margin-bottom:18px}.brand:before{content:"";display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--b);box-shadow:0 0 20px var(--b);margin-right:10px}h1{font-size:clamp(2.6rem,8vw,5.4rem);line-height:.96;letter-spacing:-.06em;margin:0;max-width:800px}.grad{background:linear-gradient(90deg,#fff,#b8aaff 48%,#65e2c5);background-clip:text;color:transparent}.sub{color:var(--muted);font-size:1.05rem;line-height:1.7;max-width:680px;margin:24px 0 32px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:26px;padding:20px;box-shadow:0 28px 80px #0007;backdrop-filter:blur(18px)}form{display:grid;grid-template-columns:minmax(0,1fr) 180px auto;gap:11px}input,select,button,a{min-height:56px;border-radius:15px;font:inherit}input,select{width:100%;border:1px solid var(--line);outline:0;background:#090c12d9;color:var(--text);padding:0 16px}input:focus,select:focus{border-color:#785cffcc;box-shadow:0 0 0 4px #785cff1f}button,a{border:0;padding:0 22px;background:linear-gradient(135deg,var(--a),#5e8cff);color:white;font-weight:750;display:inline-flex;align-items:center;justify-content:center;text-decoration:none;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.status{display:none;margin-top:16px;padding:20px;border-radius:20px;background:#090c129c;border:1px solid var(--line)}.status.show{display:block}.top{display:flex;justify-content:space-between;gap:16px}.title{font-weight:750;overflow-wrap:anywhere}.msg{color:var(--muted);font-size:.9rem;margin-top:5px}.pct{font-weight:800}.track{height:11px;background:#ffffff12;border-radius:999px;overflow:hidden;margin:18px 0 14px}.bar{height:100%;width:0;background:linear-gradient(90deg,var(--a),#6b8cff,var(--b));transition:width .3s}.bar.wait{width:35%;animation:move 1.2s infinite}@keyframes move{from{transform:translateX(-120%)}to{transform:translateX(380%)}}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.metric{padding:11px 13px;border-radius:13px;background:#ffffff0a;border:1px solid #ffffff0a}.metric small{display:block;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;font-size:.67rem;margin-bottom:5px}.metric span{font-size:.9rem}.actions{display:none;gap:10px;margin-top:16px;flex-wrap:wrap}.actions.show{display:flex}.secondary{background:#ffffff10;border:1px solid var(--line)}.error{display:none;margin-top:14px;padding:12px 14px;border:1px solid #ff708644;background:#ff708618;color:#ffdce2;border-radius:13px;overflow-wrap:anywhere}.error.show{display:block}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}.card{padding:17px;border-radius:18px;border:1px solid var(--line);background:#121722a8}.card b{display:block;margin-bottom:6px}.card span{color:var(--muted);font-size:.86rem;line-height:1.5}footer{text-align:center;color:#687487;font-size:.78rem;margin-top:26px}@media(max-width:720px){main{padding-top:38px}form{grid-template-columns:1fr}.metrics,.cards{grid-template-columns:1fr}.panel{padding:15px}}
</style></head><body><main><div class="brand">downloader local</div><h1>Baixe mídia sem <span class="grad">malabarismo.</span></h1><p class="sub">Cole o link, escolha a qualidade e acompanhe download, conversão e preparação em tempo real.</p><section class="panel"><form id="f"><input id="u" type="url" placeholder="https://youtube.com/watch?v=..." required><select id="q"><option value="best">Melhor qualidade</option><option value="1080p">1080p</option><option value="720p">720p</option><option value="480p">480p</option><option value="audio">MP3 192 kbps</option></select><button id="go">Baixar</button></form><div id="err" class="error"></div><div id="st" class="status"><div class="top"><div><div id="ti" class="title">Preparando download</div><div id="m" class="msg">Aguardando servidor...</div></div><div id="pc" class="pct">0%</div></div><div class="track"><div id="bar" class="bar wait"></div></div><div class="metrics"><div class="metric"><small>Velocidade</small><span id="sp">—</span></div><div class="metric"><small>Restante</small><span id="et">—</span></div><div class="metric"><small>Transferido</small><span id="sz">—</span></div></div><div id="ac" class="actions"><a id="dl">Salvar arquivo</a><button id="new" class="secondary" type="button">Novo download</button></div></div></section><section class="cards"><div class="card"><b>Vídeo e áudio</b><span>Melhor qualidade, 1080p, 720p, 480p e MP3.</span></div><div class="card"><b>Progresso real</b><span>Fila, velocidade, tempo restante e conversão.</span></div><div class="card"><b>Limpeza automática</b><span>Arquivos temporários expiram para preservar o disco.</span></div></section><footer>Interface web na porta 7776</footer></main>
<script>
const $=x=>document.getElementById(x),f=$('f'),u=$('u'),q=$('q'),go=$('go'),st=$('st'),ti=$('ti'),m=$('m'),pc=$('pc'),bar=$('bar'),sp=$('sp'),et=$('et'),sz=$('sz'),ac=$('ac'),dl=$('dl'),nw=$('new'),er=$('err');let timer;function b(n){n=Number(n||0);if(!n)return'—';let a=['B','KB','MB','GB'],i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),3);return(n/1024**i).toFixed(i>1?1:0)+' '+a[i]}function fail(x){er.textContent=x;er.classList.add('show')}async function j(r){let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||d.description||'Erro '+r.status);return d}function draw(x){st.classList.add('show');ti.textContent=x.title||'Preparando download';m.textContent=x.message||'Processando...';let p=Number(x.progress||0),k=['downloading','processing','ready'].includes(x.status);bar.classList.toggle('wait',!k);bar.style.width=k?Math.max(0,Math.min(p,100))+'%':'35%';pc.textContent=k?Math.round(p)+'%':'…';sp.textContent=x.speed||'—';et.textContent=x.eta||'—';sz.textContent=x.total_bytes?b(x.downloaded_bytes)+' / '+b(x.total_bytes):b(x.size||x.downloaded_bytes);if(x.status==='ready'){go.disabled=false;ac.classList.add('show');dl.href=x.download_url;dl.download=x.filename||'download'}if(x.status==='error'){go.disabled=false;fail(x.error||'Falha no download')}}async function poll(p){try{let x=await j(await fetch(p));draw(x);if(!['ready','error'].includes(x.status))timer=setTimeout(()=>poll(p),900)}catch(e){go.disabled=false;fail(e.message)}}f.onsubmit=async e=>{e.preventDefault();er.classList.remove('show');ac.classList.remove('show');go.disabled=true;st.classList.add('show');ti.textContent='Enviando link';m.textContent='Validando URL...';bar.classList.add('wait');pc.textContent='…';try{let d=await j(await fetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:u.value.trim(),quality:q.value})}));poll(d.status_url)}catch(e){go.disabled=false;fail(e.message)}};nw.onclick=()=>{clearTimeout(timer);u.value='';st.classList.remove('show');ac.classList.remove('show');er.classList.remove('show');go.disabled=false;u.focus()};
</script></body></html>'''
